p=Path('tools/asset-variety/validate.py');s=p.read_text().replace("assert old.crop((0,0,144,144)).tobytes()==new.crop((0,0,144,144)).tobytes();checks.append('Existing Pink Ninja pixels preserved')", "from PIL import ImageChops\na=old.crop((0,0,144,144));b=new.crop((0,0,144,144));bg=Image.new('RGBA',(144,144),(32,40,48,255));diff=ImageChops.difference(Image.alpha_composite(bg,a),Image.alpha_composite(bg,b));assert max(v[1] for v in diff.getextrema())<=2;checks.append('Existing Pink Ninja appearance preserved (alpha-rounding tolerance2)')");p.write_text(s)
